import{d as e,i as t}from"./index-BVdLvPw-.js";import{t as n}from"./BlogPost-BCN0DswP.js";var r=t();function i(){return(0,r.jsxs)(n,{path:`/blog-teams-phone`,children:[(0,r.jsx)(`p`,{children:`If your team already uses Microsoft Teams for chat and meetings, Teams Phone lets them make and take regular phone calls from the same app on a laptop, mobile or desk phone.`}),(0,r.jsx)(`p`,{children:`Instead of a separate phone system in a cupboard, your business phone service runs in the cloud and is managed in the Teams admin centre. Staff can answer the office number from home, transfer a call to a colleague with a click, and see who is available before they put a caller through. For businesses that already live in Microsoft 365, it often means one less system to manage.`}),(0,r.jsx)(`h2`,{children:`How Teams Phone works`}),(0,r.jsx)(`p`,{children:`Teams Phone adds the calling features: dialling, transfers, voicemail, call forwarding, auto attendants and call queues. On its own it doesn't connect to the public phone network. For that you need a connection to a phone carrier, which supplies your numbers and carries calls to and from landlines and mobiles.`}),(0,r.jsx)(`p`,{children:`Microsoft offers several ways to make that connection:`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Microsoft Calling Plans:`}),` Microsoft acts as your phone carrier. At the time of writing, Microsoft's availability page lists Calling Plans as not available to buy in Australia, so most Australian businesses use one of the other options.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Operator Connect:`}),` a certified carrier links its service to your Teams tenant. You choose the operator, then manage numbers and users in Teams. This is usually the simplest route for Australian small and medium businesses.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Direct Routing:`}),` you connect any carrier through a certified session border controller (SBC), either run by you or provided as a managed service. It suits more complex setups, such as keeping an existing carrier contract or connecting older equipment.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Teams Phone Mobile:`}),` with a participating mobile carrier, a user's mobile SIM number also becomes their Teams number.`]})]}),(0,r.jsx)(`p`,{children:`Availability changes over time, so check Microsoft's country availability pages and the Operator Connect directory on learn.microsoft.com before you decide.`}),(0,r.jsx)(`h2`,{children:`What you need`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsx)(`li`,{children:`A Teams Phone licence for each user who makes calls.`}),(0,r.jsx)(`li`,{children:`A calling plan or a connection to a phone carrier.`}),(0,r.jsx)(`li`,{children:`Phone numbers, either new or ported from your current provider.`}),(0,r.jsx)(`li`,{children:`Optional: compatible desk phones and headsets.`})]}),(0,r.jsxs)(`p`,{children:[`Teams Phone is sold as an add-on licence, and it is included in some higher-tier enterprise plans. Each calling user also needs Teams itself through their Microsoft 365 plan or a standalone Teams licence. Microsoft has changed how Teams is bundled in recent years, so confirm which version of each plan you have. Our `,(0,r.jsx)(e,{to:`/microsoft-licensing`,children:`Microsoft licensing`}),` team can check your current subscriptions and recommend the right mix for Australian businesses.`]}),(0,r.jsx)(`p`,{children:`You will also want reliable internet. Calls run over your connection, so check your bandwidth and Wi-Fi coverage, especially if several people are on calls at once.`}),(0,r.jsx)(`h2`,{children:`Keep your numbers`}),(0,r.jsx)(`p`,{children:`Most existing landline, 1300 and 1800 numbers can be ported, so customers keep calling the same numbers.`}),(0,r.jsx)(`p`,{children:`Porting is handled by your new carrier. They will usually ask for a recent bill from your current provider, your account number and an authority form signed by the account holder. The details on the form must match the old account exactly, or the port can be rejected and delayed.`}),(0,r.jsx)(`p`,{children:`A sensible porting process looks like this:`}),(0,r.jsxs)(`ol`,{children:[(0,r.jsx)(`li`,{children:`List every number you have, including fax lines, 1300 and 1800 numbers and any numbers that only forward somewhere.`}),(0,r.jsx)(`li`,{children:`Check your current contract for exit terms before you start.`}),(0,r.jsx)(`li`,{children:`Set up Teams Phone, users and call flows first, using temporary numbers for testing.`}),(0,r.jsx)(`li`,{children:`Lodge the port request with your new carrier and agree a cutover date.`}),(0,r.jsx)(`li`,{children:`Don't cancel your old service yourself. Cancelling before the port completes can mean losing the number.`}),(0,r.jsx)(`li`,{children:`After cutover, test inbound and outbound calls on every number, including after-hours routing and voicemail.`})]}),(0,r.jsxs)(`p`,{children:[`If you're weighing up which number types to keep, our guide to `,(0,r.jsx)(e,{to:`/blog-1300-vs-1800-numbers`,children:`1300 vs 1800 numbers`}),` explains the differences, and our `,(0,r.jsx)(e,{to:`/toll-free-number`,children:`toll-free number`}),` service covers 1800 numbers in more detail.`]}),(0,r.jsx)(`h2`,{children:`Add call flows`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsx)(`li`,{children:`Auto attendants (IVR menus) to route callers.`}),(0,r.jsx)(`li`,{children:`Call queues for sales or support teams.`}),(0,r.jsx)(`li`,{children:`Business hours and holiday routing.`})]}),(0,r.jsx)(`p`,{children:`An auto attendant greets callers and offers options, such as "Press 1 for sales, 2 for accounts". A call queue then rings a group of people, either all at once or in turn, and plays hold music until someone answers. You can set different routes for business hours, after hours and public holidays, for example sending after-hours calls to voicemail or an on-call mobile.`}),(0,r.jsx)(`p`,{children:`Keep menus short. Two or three options are usually enough for a small business. Long menus frustrate callers and lead to more hang-ups.`}),(0,r.jsx)(`h2`,{children:`Common mistakes`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsx)(`li`,{children:`Forgetting numbers that are rarely used but still matter, such as an alarm line or an old number printed on vehicles.`}),(0,r.jsx)(`li`,{children:`Not setting emergency addresses. Make sure each location is recorded correctly so emergency (000) calls carry accurate location details, and check with your carrier how this works for remote staff.`}),(0,r.jsx)(`li`,{children:`Skipping user training. A short session on answering, transferring and using voicemail avoids lost calls in the first week.`}),(0,r.jsx)(`li`,{children:`Relying on poor Wi-Fi. Call quality problems are often a network issue, not a Teams issue.`}),(0,r.jsx)(`li`,{children:`Porting on a busy day. Choose a quieter period and have someone ready to test.`})]}),(0,r.jsx)(`h2`,{children:`Quick checklist`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsx)(`li`,{children:`Teams Phone licence for every calling user.`}),(0,r.jsx)(`li`,{children:`Carrier chosen (Operator Connect or Direct Routing in most Australian cases).`}),(0,r.jsx)(`li`,{children:`All numbers listed and port paperwork ready.`}),(0,r.jsx)(`li`,{children:`Auto attendants, queues and holiday hours set up and tested.`}),(0,r.jsx)(`li`,{children:`Emergency addresses configured.`}),(0,r.jsx)(`li`,{children:`Headsets or desk phones that are certified for Teams.`}),(0,r.jsx)(`li`,{children:`Internet and Wi-Fi checked for call quality.`})]}),(0,r.jsx)(`h2`,{children:`Frequently asked questions`}),(0,r.jsx)(`h3`,{children:`Can I keep my existing desk phones?`}),(0,r.jsx)(`p`,{children:`Only if they are certified for Teams or supported through your carrier's setup. Many older handsets aren't. Teams-certified desk phones and headsets give the most reliable experience.`}),(0,r.jsx)(`h3`,{children:`Can staff use the business number from their mobile?`}),(0,r.jsx)(`p`,{children:`Yes. With the Teams app on their phone, staff can make and take calls from the business number, so their personal number stays private.`}),(0,r.jsx)(`h3`,{children:`What happens to calls if our office internet goes down?`}),(0,r.jsx)(`p`,{children:`Because the service runs in the cloud, staff can keep working from the mobile app over mobile data. You can also set call forwarding rules as a backup.`}),(0,r.jsx)(`h3`,{children:`How long does porting take?`}),(0,r.jsx)(`p`,{children:`It depends on the carriers and number types involved. Simple ports can be quick, while 1300 and 1800 numbers or multi-number ports often take longer. Your new carrier will give you an estimate when you lodge the request.`}),(0,r.jsxs)(`p`,{children:[`Teams Phone is one part of a wider `,(0,r.jsx)(e,{to:`/microsoft`,children:`Microsoft 365`}),` setup. See our `,(0,r.jsx)(e,{to:`/landline-number`,children:`Landline Number`}),` and `,(0,r.jsx)(e,{to:`/ivr-system`,children:`IVR System`}),` services.`]})]})}export{i as default};